function updateOutfit(){document.querySelector('#avatar').innerHTML=avatarSvg();renderChallenge();renderItems()}
document.querySelector('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;state.tab=b.dataset.tab;save();renderItems()});
document.querySelector('#items').addEventListener('click',e=>{const btn=e.target.closest('[data-item]');if(!btn)return;const item=Object.values(catalog).flat().find(i=>i.id===btn.dataset.item);if(!item)return;if(!state.owned.includes(item.id)){if(state.coins<item.price){showToast('You need a few more coins for this piece.');return}state.coins-=item.price;state.owned.push(item.id);showToast(`${item.name} added to your wardrobe!`)}state.equipped[state.tab]=item.id;save();render();});
document.querySelector('#randomBtn').addEventListener('click',()=>{const tags=challenges[state.challenge].tags;for(const [cat] of categories){let options=catalog[cat].filter(item=>state.owned.includes(item.id));let matching=options.filter(item=>item.tags.some(t=>tags.includes(t)));let pool=matching.length?matching:options;state.equipped[cat]=pool[Math.floor(Math.random()*pool.length)].id}save();render();showToast('A little styling magic ✨')});
document.querySelector('#submitBtn').addEventListener('click',()=>{if(state.completed.includes(state.challenge))return;const score=matchScore();const coins=25+Math.round(score*.45),stars=score>=80?3:score>=50?2:1;state.coins+=coins;state.stars+=stars;state.completed.push(state.challenge);save();render();document.querySelector('#resultMedal').textContent=score>=80?'🏆':score>=50?'🌟':'💖';document.querySelector('#resultTitle').textContent=score>=80?'A star is born!':score>=50?'Lovely styling!':'A sweet first look!';document.querySelector('#resultScore').textContent=score;document.querySelector('#resultCopy').textContent=score>=80?'You understood the mood perfectly. The whole room is looking your way!':score>=50?'Your look has a lovely mood. Try matching more of the challenge colors for an even bigger score.':'Every star starts somewhere. Try adding a few challenge colors to your look!';document.querySelector('#resultReward').textContent=`+${stars} ✦   +${coins} 🪙`;document.querySelector('#continueBtn').textContent='Next challenge';document.querySelector('#modal').classList.add('open')});
document.querySelector('#continueBtn').addEventListener('click',()=>{document.querySelector('#modal').classList.remove('open');if(state.completed.includes(state.challenge)){state.challenge=(state.challenge+1)%challenges.length;if(state.completed.length===challenges.length)state.completed=[];save();render()}});
document.querySelector('#modal').addEventListener('click',e=>{if(e.target.id==='modal')document.querySelector('#modal').classList.remove('open')});
document.querySelector('#nameBtn').addEventListener('click',()=>{const name=prompt('What should we call your star?',state.name);if(name&&name.trim()){state.name=name.trim().slice(0,16);save();render();showToast(`Looking lovely, ${state.name}!`)}});
document.querySelector('.nav').addEventListener('click',e=>{const b=e.target.closest('[data-nav]');if(!b)return;document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.nav==='collection'){document.querySelector('.wardrobe').scrollIntoView({behavior:'smooth',block:'center'});showToast('Your closet, your rules.')}if(b.dataset.nav==='studio'){document.querySelector('.studio').scrollIntoView({behavior:'smooth',block:'center'})}if(b.dataset.nav==='lookbook'){document.querySelector('#resultMedal').textContent='📖';document.querySelector('#resultTitle').textContent='Your lookbook';document.querySelector('#resultScore').textContent=state.stars;document.querySelector('.notice').textContent='TOTAL STARS EARNED';document.querySelector('#resultCopy').textContent=state.completed.length?`You’ve styled ${state.completed.length} challenge${state.completed.length===1?'':'s'} so far. Keep collecting stars and creating new looks!`:'Your story starts with the next look you create. Complete a challenge to add a page!';document.querySelector('#resultReward').textContent=`${state.owned.length} wardrobe pieces · ${state.coins} coins`;document.querySelector('#continueBtn').textContent='Back to styling';document.querySelector('#modal').classList.add('open')}});
render();
</script>
</body>
</html>

