@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--ink:#33244b;--muted:#9a8ba9;--pink:#f27dad;--purple:#9672d8;--line:#f0e8f4;--card:#fff;--bg:#fcf9ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible{outline:3px solid #bba2ed;outline-offset:3px}.app{max-width:1480px;margin:auto;padding:0 36px 36px}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #f1eaf5}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:42px;height:42px;border-radius:15px;background:linear-gradient(145deg,#f6a4c4,#a889e7);display:grid;place-items:center;color:#fff;font-size:23px;box-shadow:0 7px 18px #e6c6eb}.brand-name{font:800 21px 'Playfair Display',serif;letter-spacing:-.4px}.brand-name span{color:#bb8bd8}.nav{display:flex;gap:8px;margin-left:10%}.nav button{background:transparent;border:0;border-radius:18px;padding:11px 16px;color:#8c7d9c;font-size:13px;font-weight:700}.nav button.active,.nav button:hover{background:#f7ecfa;color:#a35baf}.wallet{display:flex;gap:10px}.wallet-pill{display:flex;align-items:center;gap:7px;background:#fff;border:1px solid var(--line);border-radius:18px;padding:9px 13px;font-size:13px;font-weight:800;box-shadow:0 4px 12px #50356b08}.wallet-pill span:first-child{font-size:16px}.page-head{display:flex;align-items:flex-end;justify-content:space-between;padding:27px 2px 22px}.eyebrow{font-size:10px;letter-spacing:2px;font-weight:800;text-transform:uppercase;color:#b486c9;margin-bottom:8px}.page-head h1{font:700 29px 'Playfair Display',serif;margin:0;letter-spacing:-.5px}.page-head p{margin:6px 0 0;color:var(--muted);font-size:13px}.season-pill{background:#fff;border:1px solid var(--line);border-radius:20px;padding:9px 14px;font-size:11px;font-weight:800;color:#907ba7}.layout{display:grid;grid-template-columns:minmax(380px,.92fr) minmax(510px,1.08fr);gap:22px;align-items:stretch}.studio{position:re