function renderItems(){let active=state.tab;document.querySelector('#tabs').innerHTML=categories.map(([id,label])=>`<button class="tab ${active===id?'selected':''}" data-tab="${id}">${label}</button>`).join('');document.querySelector('#items').innerHTML=catalog[active].map(row=>{let i=itemMap[row[0]],owned=state.owned.includes(i.id),equipped=state.equipped[active]===i.id;return `<button class="item ${equipped?'equipped':''} ${owned?'':'locked'}" data-item="${i.id}" style="--swatch:${i.color}" aria-label="${i.name}${owned?'':`, ${i.price} coins`}"><span class="item-art">${i.emoji}</span><span class="item-name">${i.name}</span>${owned?(equipped?'<span class="check">✓</span>':''):`<span class="item-price">🪙 ${i.price}</span>`}</button>`}).join('');document.querySelector('#wardrobeCount').textContent=`${state.owned.length} pieces`}
